TLM.f("Tempora/Pent08-5",{"officium":"Feria sexta infra Hebdomadam VIII post Octavam Pentecostes","rule":["Oratio Dominica","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"fallback":"Tempora/Pent08-0","from":{"Introitus":"Tempora/Pent08-0","Oratio":"Tempora/Pent08-0","Lectio":"Tempora/Pent08-0","Graduale":"Tempora/Pent08-0","Evangelium":"Tempora/Pent08-0","Offertorium":"Tempora/Pent08-0","Secreta":"Tempora/Pent08-0","Communio":"Tempora/Pent08-0","Postcommunio":"Tempora/Pent08-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 47:10-11"},{"k":"text","la":"Suscépimus, Deus, misericórdiam tuam in médio templi tui: secúndum nomen tuum, Deus, ita et laus tua in fines terræ: justítia plena est déxtera tua."},{"k":"ref","la":"Ps 47:2"},{"k":"text","la":"Magnus Dóminus, et laudábilis nimis: in civitáte Dei nostri, in monte sancto ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Suscépimus, Deus, misericórdiam tuam in médio templi tui: secúndum nomen tuum, Deus, ita et laus tua in fines terræ: justítia plena est déxtera tua."}],"Oratio":[{"k":"text","la":"Largíre nobis, quǽsumus, Dómine, semper spíritum cogitándi quæ recta sunt, propítius et agéndi: ut, qui sine te esse non póssumus, secúndum te vívere valeámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános"},{"k":"ref","la":"Rom 8:12-17"},{"k":"text","la":"Fratres: Debitóres sumus non carni, ut secúndum carnem vivámus. Si enim secúndum carnem vixéritis, moriémini: si autem spíritu facta carnis mortificavéritis, vivétis. Quicúmque enim spíritu Dei aguntur, ii sunt fílii Dei. Non enim accepístis spíritum servitútis íterum in timóre, sed accepístis spíritum adoptiónis filiórum, in quo clamámus: Abba - Pater. - Ipse enim Spíritus testimónium reddit spirítui nostro, quod sumus fílii Dei. Si autem fílii, et herédes: herédes quidem Dei, coherédes autem Christi."}],"Graduale":[{"k":"ref","la":"Ps 30:3"},{"k":"text","la":"Esto mihi in Deum protectórem, et in locum refúgii, ut salvum me fácias."},{"k":"ref","la":"Ps 70:1"},{"k":"text","la":"Deus, in te sperávi: Dómine, non confúndar in ætérnum.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 47:2"},{"k":"text","la":"Magnus Dóminus, et laudábilis valde, in civitáte Dei nostri, in monte sancto ejus. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 16:1-9"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis parábolam hanc: Homo quidam erat dives, qui habébat víllicum: et hic diffamátus est apud illum, quasi dissipásset bona ipsíus. Et vocávit illum et ait illi: Quid hoc audio de te? redde ratiónem villicatiónis tuæ: jam enim non póteris villicáre. Ait autem víllicus intra se: Quid fáciam, quia dóminus meus aufert a me villicatiónem? fódere non váleo, mendicáre erubésco. Scio, quid fáciam, ut, cum amótus fúero a villicatióne, recípiant me in domos suas. Convocátis itaque síngulis debitóribus dómini sui, dicébat primo: Quantum debes dómino meo? At ille dixit: Centum cados ólei. Dixítque illi: Accipe cautiónem tuam: et sede cito, scribe quinquagínta. Deínde álii dixit: Tu vero quantum debes? Qui ait: Centum coros trítici. Ait illi: Accipe lítteras tuas, et scribe octogínta. Et laudávit dóminus víllicum iniquitátis, quia prudénter fecísset: quia fílii hujus sǽculi prudentióres fíliis lucis in generatióne sua sunt. Et ego vobis dico: fácite vobis amicos de mammóna iniquitátis: ut, cum defecéritis, recípiant vos in ætérna tabernácula."}],"Offertorium":[{"k":"ref","la":"Ps 17:28; 17:32"},{"k":"text","la":"Pópulum húmilem salvum fácies, Dómine, et óculos superbórum humiliábis: quóniam quis Deus præter te, Dómine?"}],"Secreta":[{"k":"text","la":"Súscipe, quǽsumus, Dómine, múnera, quæ tibi de tua largitáte deférimus: ut hæc sacrosáncta mystéria, grátiæ tuæ operánte virtúte, et præséntis vitæ nos conversatióne sanctíficent, et ad gáudia sempitérna perdúcant."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 33:9"},{"k":"text","la":"Gustáte et vidéte, quóniam suávis est Dóminus: beátus vir, qui sperat in eo."}],"Postcommunio":[{"k":"text","la":"Sit nobis, Dómine, reparátio mentis et córporis cæléste mystérium: ut, cujus exséquimur cultum, sentiámus efféctum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"7ff4bedd350271d3":{"t":"Ps 47, 10-11, Ps 47, 2\n(Ps 47, 10-11) Primili smo, Bože tvoju milost usred tvojeg hrama. Kao što je tvoje ime, Bože, tako neka bude i tvoja hvala do kraja zemlje. Pravde je puna tvoja desnica. (Ps 47, 2) Velik je Gospodin i veoma dostojan hvale u gradu Boga našega, na svetoj gori njegovoj.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 47, 10-11) Primili smo, Bože tvoju milost usred tvojeg hrama. Kao što je tvoje ime, Bože, tako neka bude i tvoja hvala do kraja zemlje. Pravde je puna tvoja desnica.","kn":"(Ps. 47,\" 10). Primili smo, .Bože, milosrđe .Tvoje usred hrama\" Tvojega. Kao što. ime Tvoje, Bože, tako i hvala Tvoja dopire do krajeva zemaljskih; pravde je puna desnica Tvoja. (Ps. 47, 2),' Velik je Gospodin i slavan veoma u gradu Boga našega, na svetoj gori svojoj. Slava Ocu . . . Primili smo . . .","knRef":"Kniewald 1942, str. 384–385 (snimka 193) (OCR)"},"0f7f0909e5c09568":{"t":"<i>Pomolimo se</i>.\nObdari nas milostivo, molimo, Gospodine, duhom da uvijek nastojimo i radimo što je pravedno, da tako mi, koji bez tebe ne možemo opstojati, možemo živjeti po tvojoj volji.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Daruj nam, molimo, Gospodine, milostivo .‘rveudilj duh, da mislimo i radimo što je pravo, te, koji bez Tebe ne možemo biti, budemo vrsni po Tebi živjeti, po G. n.","knRef":"Kniewald 1942, str. 386–387 (snimka 194) (OCR)"},"cd98322ded72de89":{"t":"Rim 8, 12-17\nČitanje Poslanice bl. Pavla apostola Rimljanima. Braćo, nismo dužnici tijelu, da bismo živjeli po tijelu. Ako budete živjeti po tijelu, doista ćete umrijeti, ako pak budete mrtvili tjelesna djela, živjet ćete. Božja su djeca oni koje vodi Božji Duh. A vi niste primili duha ropstva da se i nadalje bojite, nego ste primili duh posinaštva po kojem zazivamo: Abba, Oče! Taj Duh svjedoči našem duhu da smo Božja djeca. Ako smo djeca, onda smo i baštinici, baštinici Božji i subaštinici Kristovi.","kn":"Čitanje poslanice bi. Pavla apostola Rimljanima (8, 12-17). Braćo! Ne dugujemo tijelu, da živimo po tijelu. Jer ako budete živjeli po tijelu, umrijet ćete, a živjet ćete, ako budete duhom morili tjelesna djela. Božja su djeca oni, koje vodi Duh Božji. Jer nijesite primili duha ropstva, da se opet bojite, nego ste primili Duha posinaStva, kojim nazivamo: Abba, Oče! Ovaj isti Duh svjedoči našemu duhu, da smo Božja djeca. Ako smo djeca; onda smo 1 baštihlci: baštinici Božji i subaštinici. Kristovi.","knRef":"Kniewald 1942, str. 386–387 (snimka 194) (OCR)"},"6dd5f3665efdae8d":{"t":"Ps 30, 3, Ps 70, 1\n(Ps 30, 3) Budi mi Bog, branitelj i mjesto utočišta da me izbaviš. (Ps 70, 1) Bože, u tebe se uzdam, neću se smesti do vijeka.\n\nPs 47, 2\n<i>Aleluja</i>, <i>aleluja</i>.\nVelik je Gospodin i veoma dostojan hvale u gradu Boga našega, na svetoj gori njegovoj. <i>Aleluja</i>.","kn":"(Ps, 30, 3). Budi mi Bog zaštitnik i kuća utočišta da me spasiš. Bože, u Tebe se uzdam; Gospodine, ne ću se postidjeli u vijeke.\n\nAleluja, aleluja. (Ps. 47, 2) Velik je Gospodin, i slavan veoma, u gradu Boga našega, na svetoj gori svojoj.","knRef":"Kniewald 1942, str. 386–387 (snimka 194) (OCR)"},"e4b7dd385a17f2fc":{"t":"Lk 16, 1-9\nSlijedi sveto Evanđelje po Luki. U ono vrijeme reče Isus svojim učenicima ovu usporedbu: Neki je bogataš imao upravitelja kojega su optužili da rasipa dobra njegova. On ga dozva i reče mu: Što to čujem o tebi? Položi račun o svom upravljanju, jer više ne možeš biti upraviteljem. Tada je upravitelj smišljao u sebi: Što da učinim, jer mi gospodar oduzima upravu. Kopati ne mogu, prosjačiti se stidim. Ali znam što ću učiniti, da me netko primi k sebi kad me uklone s uprave. I pozove k sebi dužnike svoga gospodara, pa upita prvoga: Koliko ti duguješ mojem gospodaru? On odgovori: Sto bačava ulja. Reče mu: Uzmi svoju obveznicu, odmah sjedi i napiši: pedeset. Onda upita drugoga: A ti koliko duguješ? Ovaj odgovori: Sto mjera pšenice. Reče mu: Uzmi svoju obveznicu i napiši: osamdeset. I gospodar istakne, da je nevjerni upravitelj mudro postupio. Doista, djeca su ovoga svijeta dovitljivija od djece svjetlosti. I ja vama kažem: Stičite sebi prijetelje prolaznim bogatstvom, da vas, kad umrete, prime u svoje vječne stanove.","kn":"t Slijedi sveto evanđelje po Luki (16, 1-9). U ono vrijeme reče Isus svojim učenicima': Bio je neki bogataš, koji je imao upravitelja. Ovaj je bio kod nje'ga optužen kao da rasipa njegova dobra. I dozove ga i reče mu: Sto to čujem o tebi? Položi račun, kako si upravljao, jer više ne možeš biti upravitelj. Taida upravitelj rekne u sebi: Sto ću učiniti, jer mi moj gospodar oduzimlje upravu? Kapati ne mogu, a stidim se prositi. Znam, što ću učiniti, da me prime u svoje kuće, kad me uklone od uprave. I pozove redom dužnike svojega gospodara i upita prvoga: Koliko duguješ mojemu gospodaru? Oh mu odgovori: Sto bačava ulja. Rekne mu: Uzmi svoju obveznicu, brzo sjedi i napiši pedeset. Upita zatim drugoga: A koliko duguješ ti? Ovaj odgovori: Sto mjera pšenice. Reče mu: Uzmi svoju zadužnicu i napiši osamdeset. I gospodar pohvali nepravednog upravitelja, da je radio panietno, jer. su sinovi ovoga svijeta pametniji u svomu naraštaju od sinova svijetla. I ja vam kažem: Stecite sebi prijatelje nepravednim bogatstvom, da, kada klonete, prime vas u vječne stanove.","knRef":"Kniewald 1942, str. 386–387 (snimka 194) (OCR)"},"d343580f72dbf9b4":{"t":"Ps 17, 28 i 32\nTi spašavaš ponizan puk, Gospodine, a ponizuješ oči oholih, jer tko je Bog osim tebe, Gospodine?","kn":"(Ps. 17, 28, 32). Spasit ćeš. Gospodine, narod ponizan, a ponizit ćeš oči oholih: jer tko je Bog, osim Tebe, Gospodine?","knRef":"Kniewald 1942, str. 386–387 (snimka 194) (OCR)"},"f003aa5698368ec6":{"t":"Primi, molimo, Gospodine, darove što ti ih prinosimo od tvoje darežljivosti, da nas ova sveta otajstva snagom svoje milosti posvećuju u sadašnjem životu i privedu u vječne radosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primi, molimo, Gospodine, darove, što ih prinosimo od Tvo'je darežljivosti; da nas ove presvete tajne djelovanjem Tvoje krepke milosti i posvete krejiosnim življenjem sadašnjega života i dovedu u radosti vječne, po G. ru","knRef":"Kniewald 1942, str. 386–387 (snimka 194) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"3649d83821aefc7e":{"t":"Ps 33, 9\nKušajte i vidite kako je ugodan Gospodin. Blago čovjeku koji se uzda u njega.","kn":"(Ps. 33, 9). Kušajte i vidite, kako je sladak Gospodin; blago čovjeku, koji se uzda u nj.","knRef":"Kniewald 1942, str. 386–387 (snimka 194) (OCR)"},"fef6cca751926ef1":{"t":"<i>Pomolimo se</i>.\nBilo nam nebesko otajstvo, Gospodine, na obnovu duše i tijela da osjetimo učinak onoga što štujemo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bilo narii nebesko otajstvo, Gospodine, obnova duše i tijela, da dćutimo učinak onoga, što poštujemo i izvršujemo, po G. n.","knRef":"Kniewald 1942, str. 386–387 (snimka 194) (OCR)"}}});
